// Destino canónico para un id de radar. Si el id no está en la tabla
// (no debería ocurrir: la tabla cubre los 961 ids del dataset), enlaza al
// índice /radares/ (vivo, sin 301) en vez de a una URL con 301.
export function destinoRadar(id: string): string {
  const slug = RADAR_A_MULTAS[id];
  return slug ? `/multas/${slug}/` : "/radares/";
}
